                "हडप्पा समाजावर एकच सम्राट राज्य करत होता असे ठामपणे सांगता येत नाही.",
                "केंद्रीकृत राज्य, अनेक शहरी केंद्रे किंवा विविध प्रकारच्या स्थानिक सत्ताकेंद्रांचे सिद्धांत मांडले गेले आहेत."
