                "जैन धर्म आत्म्याचे किंवा जीवाचे अस्तित्व मानतो; बौद्ध धर्म अनात्मवाद मांडतो.",
                "जैन धर्मात कठोर तपश्चर्येला मोठे महत्त्व आहे; बुद्धांनी अति तपश्चर्या नाकारून मध्यम मार्ग सांगितला.",
                "जैन आणि बौद्ध धर्मामुळे भारतीय समाजात नवीन नैतिक, तात्त्विक आणि धार्मिक विचारांना चालना मिळाली.",
