                "कृषी, व्यापार, नगरांचा विकास आणि करव्यवस्था यांमुळे राज्यसत्तेची आर्थिक क्षमता वाढत होती.",
                "याच काळात प्रादेशिक राज्यांमध्ये वर्चस्वासाठी संघर्ष वाढला आणि मगध सर्वांत प्रभावशाली शक्ती म्हणून पुढे आले."
