                "कुषाण आणि सातवाहन सत्तांच्या ऱ्हासानंतर भारतात अनेक प्रादेशिक राज्ये उदयास आली.",
                "इ.स.च्या तिसऱ्या–चौथ्या शतकात उत्तर भारतात राजकीय पुनर्रचनेची प्रक्रिया सुरू झाली.",
