                "गुप्त वंशातील प्रारंभिक शासक म्हणून श्रीगुप्त आणि घटोत्कच यांचा उल्लेख आढळतो.",
                "प्रारंभी गुप्तांची सत्ता मर्यादित प्रादेशिक स्वरूपाची असावी.",
                "चंद्रगुप्त प्रथम याने गुप्त सत्तेला अधिक मजबूत राजकीय स्वरूप दिले.",
                "चंद्रगुप्त प्रथमने ‘महाराजाधिराज’ ही पदवी धारण केली.",
                "त्याचा विवाह लिच्छवी राजकन्या कुमारदेवीशी झाला.",
