                "चंद्रगुप्त प्रथम हा गुप्त साम्राज्याच्या विस्तारातील महत्त्वाचा प्रारंभिक शासक होता.",
                "त्याने गुप्त सत्तेला अधिक संघटित आणि प्रभावी स्वरूप दिले.",
