                "गुप्तकालीन सुवर्ण नाणी आर्थिक व्यवहार आणि राजकीय सामर्थ्याचे महत्त्वाचे पुरावे आहेत.",
                "भूमिदानाच्या वाढीमुळे ग्रामीण अर्थव्यवस्थेत आणि स्थानिक सत्तासंबंधात महत्त्वाचे बदल झाले.",
