                "ब्राह्मण आणि क्षत्रिय वर्गांना सामाजिक प्रतिष्ठा मोठ्या प्रमाणावर होती.",
                "वैश्य वर्गाचा संबंध व्यापार, कृषी आणि आर्थिक व्यवहारांशी होता.",
