                "आस्तिक म्हणजे वेदांचे प्रमाणत्व स्वीकारणारे दर्शन; याचा अर्थ केवळ ईश्वरावर विश्वास ठेवणारे असा नाही.",
                "षड्दर्शनांमध्ये सांख्य, योग, न्याय, वैशेषिक, पूर्वमीमांसा आणि वेदांत यांचा समावेश होतो.",
