                "सांख्य तत्त्वज्ञानात दोन मूलभूत तत्त्वे आहेत — पुरुष आणि प्रकृती.",
                "पुरुष हे चेतन तत्त्व असून प्रकृती हे अचेतन आणि परिवर्तनशील तत्त्व आहे.",
                "प्रकृतीमध्ये सत्त्व, रज आणि तम हे तीन गुण आहेत.",
                "पुरुष आणि प्रकृती यांच्या संयोगामुळे अनुभवाचे विश्व निर्माण होते.",
                "पुरुषाने स्वतःचे प्रकृतीपासून वेगळेपण जाणणे म्हणजे मुक्तीकडे जाणे.",
                "सांख्य परंपरेला सामान्यतः ईश्वरनिरपेक्ष तत्त्वज्ञान मानले जाते.",
                "योग दर्शनाचा संबंध पतंजलींच्या योगसूत्रांशी जोडला जातो.",
