                "प्रमुख पदार्थांमध्ये द्रव्य, गुण, कर्म, सामान्य, विशेष आणि समवाय यांचा समावेश होतो.",
                "पुढील परंपरेत अभाव हाही पदार्थ मानला गेला.",
                "वैशेषिक दर्शनात परमाणुवादाचा महत्त्वपूर्ण विकास दिसतो.",
                "पुढे न्याय आणि वैशेषिक दर्शनांचा परस्पर जवळचा संबंध निर्माण झाला."
