                "अशा भूमिदानांची माहिती ताम्रपट आणि शिलालेखांमधून मिळते.",
                "काही भूमिदानांमध्ये करसवलती किंवा महसूल वसुलीशी संबंधित अधिकारही दिले जात.",
                "स्थानिक जमीनधारक आणि सरदारांचे आर्थिक व राजकीय महत्त्व वाढले.",
