                "भारताच्या सर्व प्रदेशांमध्ये एकसारखी सामंतशाही होती असे मानणे योग्य नाही.",
                "भूमिदानामुळे प्रशासन, ग्रामीण अर्थव्यवस्था आणि स्थानिक सत्तासंबंधांमध्ये महत्त्वाचे बदल झाले."
