                "भूमिदानामुळे काही भागांत जमीन, महसूल आणि श्रम यांच्यावर स्थानिक अधिकार वाढले.",
                "या प्रक्रियेमुळे ग्रामीण समाजात नवीन सामाजिक आणि आर्थिक संबंध निर्माण झाले."
