                "दक्षिण भारतातील चोल काळात समुद्री व्यापाराला विशेष महत्त्व प्राप्त झाले.",
                "अरब व्यापारी आणि भारतीय बंदरांमधील संपर्कामुळे पश्चिम किनाऱ्यावरील व्यापार वाढला.",
                "या काळात व्यापार पूर्णपणे नष्ट झाला असे म्हणणे अयोग्य आहे; प्रदेशानुसार व्यापार आणि नागरीकरणाचे स्वरूप बदलले."
